export function createWrittenCueDrawing(cue,index,view,bank=letters){
  const area=farmGuidanceArea(view),count=[...cue.text].length;
  const columns=Math.max(4,Math.min(10,Math.round(Math.sqrt(count*area.width/area.height)))),lines=[];
  for(const original of cue.lines){const chars=original.match(/\.{3}|./gu);for(let i=0;i<chars.length;i+=columns)lines.push(chars.slice(i,i+columns).join(''));}
  const advance=letter=>letter==='.'?28:letter==='，'?52:112,lineWidth=line=>[...line].reduce((n,c)=>n+advance(c),0);
  const nativeWidth=Math.max(...lines.map((line,i)=>lineWidth(line)+(cue.sketch&&i===lines.length-1?145:0)))+24,nativeHeight=lines.length*118+14;
  const scale=Math.min(.68,(area.width-12)/nativeWidth,(area.height-10)/nativeHeight),width=nativeWidth*scale,height=nativeHeight*scale,origin={x:area.x+(area.width-width)/2,y:area.y+(area.height-height)/2},strokes=[];
  const add=(kind,points)=>strokes.push({kind,points:points.map(([x,y])=>({x:origin.x+x*scale,y:origin.y+y*scale}))});
  lines.forEach((line,row)=>{
    const chars=[...line],span=lineWidth(line)+(cue.sketch&&row===lines.length-1?145:0),start=(nativeWidth-span)/2;let cursor=start;
    chars.forEach((letter,i)=>{if(!bank[letter])throw Error(`Missing farm hint character: ${letter}`);const angle=Math.sin(i*1.8+row+index)*.045,dy=Math.sin(i*.9+index)*4;
      for(const points of bank[letter])add('letter',points.map(([x,y])=>{const px=x-50,py=y-50;return[cursor+advance(letter)/2+px*Math.cos(angle)-py*Math.sin(angle),row*118+55+dy+px*Math.sin(angle)+py*Math.cos(angle)];}));cursor+=advance(letter);
    });
    if(cue.sketch&&row===lines.length-1){const x=start+lineWidth(line)+15,y=row*118+7,sketch=(kind,points)=>add(kind,points.map(([px,py])=>[x+px,y+py]));
      sketch('thumb',[[20,58],[34,44],[43,25],[46,9],[55,3],[65,8],[67,19],[62,39],[88,38],[100,44],[103,56],[99,70],[94,84],[82,96],[47,97],[32,87],[21,85]]);
      sketch('thumb-cuff',[[6,57],[21,55],[23,88],[8,91],[6,57]]);
      sketch('thumb-fold',[[70,54],[96,55]]);sketch('thumb-fold',[[70,69],[93,69]]);sketch('thumb-fold',[[67,83],[87,83]]);
      sketch('thumb-fold',[[38,60],[51,58],[58,65],[57,79]]);
    }
  });
  return createPencilDrawing(Object.freeze({text:cue.text,cue:cue.id,lines,width:view.width,height:view.height,delay:.04,writeDuration:MECHANISM_TIMING.write,hold:MECHANISM_TIMING.hold,eraseDuration:MECHANISM_TIMING.erase,strokeScale:1.55,area}),strokes);
}
